+/**
+ * HTML sanitization utilities to prevent XSS attacks
+ */
+
+// Tags and attributes that are safe to render
+const ALLOWED_TAGS = new Set([
+  "html", "head", "body", "style", "title", "meta", "link",
+  "div", "span", "p", "br", "hr",
+  "h1", "h2", "h3", "h4", "h5", "h6",
+  "ul", "ol", "li", "table", "tr", "td", "th", "thead", "tbody",
+  "a", "img", "iframe",
+  "b", "i", "u", "strong", "em", "code", "pre", "blockquote",
+]);
+
+const ALLOWED_ATTRS = new Set([
+  "href", "src", "alt", "title", "width", "height", "style",
+  "class", "id", "target", "rel", "charset", "content", "name",
+]);
+
+/**
+ * Sanitizes HTML content to prevent XSS attacks
+ * by removing dangerous tags, attributes, and event handlers
+ */
+export const sanitizeHTML = (html: string): string => {
+  if (!html) {
+    return "";
+  }
+
+  // Create a temporary container to parse and sanitize
+  const container = document.createElement("div");
+  container.textContent = html;
+  return container.innerHTML;
+};
+
+/**
+ * Sanitizes an attribute value to prevent attribute injection
+ */
+export const sanitizeAttribute = (attr: string): string => {
+  if (!attr) {
+    return "";
+  }
+
+  // Escape HTML special characters to prevent attribute injection
+  return attr
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#x27;")
+    .replace(/\//g, "&#x2F;");
+};
+
+/**
+ * Checks if a URL is safe to embed
+ */
+export const isSafeEmbedURL = (url: string): boolean => {
+  if (!url) {
+    return false;
+  }
+
+  try {
+    const parsed = new URL(url);
+    // Only allow https URLs and specific protocols
+    return parsed.protocol === "https:" || parsed.protocol === "data:";
+  } catch {
+    return false;
+  }
+};
