+// HTML encoding utility for XSS prevention
+// Encodes special HTML characters to prevent XSS attacks
+
+function encodeHTML(str) {
+  if (str === null || str === undefined) {
+    return '';
+  }
+  
+  return String(str)
+    .replace(/&/g, '&amp;')
+    .replace(/</g, '&lt;')
